per_call.cmd:
cat > /app/build/config.h << 'EOF'
/* POV-Ray 2.2 Unix config.h */

/* Basic defines */
#define DBL double

/* Math functions */
#define ACOS acos
#define SQRT sqrt
#define POW pow
#define COS cos
#define SIN sin

/* Standard library functions */
#define labs(x) (long) ((x<0)?-x:x)
#define max(x,y) ((x<y)?y:x)

/* sprintf returns length (not string) */
#define STRLN(x) x

/* Define PARAMS for function prototyping */
#ifdef _STDC_
#define PARAMS(x) x
#else
#define PARAMS(x) ()
#define volatile
#endif

/*_epsilon for floating point comparisons */
#define EPSILON 1.0e-5

/* startup and cleanup */
#define STARTUP_POVRAY unix_init_POVRAY();
#define TIME_ELAPSED (tstop - tstart);

/* Need prototypes for standard routines */
char *getenv PARAMS((char *name));
char *malloc PARAMS((int size));
void free PARAMS((void *));

/* Environment variable handling - default is after povray.def */
#ifndef READ_ENV_VAR_BEFORE
#define READ_ENV_VAR_BEFORE
#endif
#ifndef READ_ENV_VAR_AFTER
#define READ_ENV_VAR_AFTER if ((Option_String_Ptr = getenv("POVRAYOPT")) != NULL) read_options(Option_String_Ptr);
#endif

/* Output format default */
#define DEFAULT_OUTPUT_FORMAT   't'
EOF
cat /app/build/config.h
